    correction: [{"quoi":"نسمّي رقم المئات","math":"نسمّي n رقم المئات، فتكون الأرقام n و <span dir=\"ltr\" class=\"expr\">n + 1</span> و <span dir=\"ltr\" class=\"expr\">n + 2</span>"},{"quoi":"شرط القسمة على 3","math":"العدد يقبل القسمة على 3 إذا كان مجموع أرقامه يقبل القسمة على 3"},{"quoi":"نحسب مجموع الأرقام","math":"<span dir=\"ltr\" class=\"expr\">n + (n + 1) + (n + 2) = 3n + 3</span>"},{"quoi":"نفكّك المجموع","math":"<span dir=\"ltr\" class=\"expr\">3n + 3 = 3(n + 1)</span>"},{"quoi":"المجموع مضاعف لـ 3","math":"المجموع مضاعف لـ 3 مهما يكن n، فالشرط محقّق دائما"},{"quoi":"الجواب","math":"صواب"}],
