    correction: [{"quoi":"القاعدة","math":"نوحّد الأساس ثمّ نضع أصغر قوّة عاملا مشتركا"},{"quoi":"نوحّد الأساس في الحدّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">4<sup>731</sup> = 2<sup>1462</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>1463</sup> + n × 2<sup>1462</sup> = 2<sup>1462</sup>(2 + n)</span>"},{"quoi":"نفكّك القاسم","math":"<span dir=\"ltr\" class=\"expr\">14 = 2 × 7</span>"},{"quoi":"العامل 2 موجود دائما","math":"<span dir=\"ltr\" class=\"expr\">2<sup>1462</sup> = 2 × 2<sup>1461</sup></span>"},{"quoi":"يبقى الشرط على 7","math":"بما أنّ 7 و 2 أوليان فيما بينهما، يجب أن يقبل <span dir=\"ltr\" class=\"expr\">2 + n</span> القسمة على 7"},{"quoi":"نحسب الحدّ الثابت","math":"<span dir=\"ltr\" class=\"expr\">2 = 2</span>"},{"quoi":"نبحث عن n","math":"نبحث عن n أصغر من 50 بحيث يقبل <span dir=\"ltr\" class=\"expr\">2 + n</span> القسمة على 7"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: 5 ؛ 12 ؛ 19 ؛ 26 ؛ 33 ؛ 40 ؛ 47</span>"}],
