    correction: [{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 9 + 36/(n + 1)</span>"},{"quoi":"الشرط","math":"9 عدد صحيح، إذن M صحيح يعني أنّ <span dir=\"ltr\" class=\"expr\">36/(n + 1)</span> عدد صحيح"},{"quoi":"نترجم","math":"<span dir=\"ltr\" class=\"expr\">n + 1</span> يجب أن يكون قاسما للعدد 36"},{"quoi":"قواسم 36","math":"قواسم 36 الموجبة هي<span dir=\"ltr\" class=\"expr\">: 1 ؛ 2 ؛ 3 ؛ 4 ؛ 6 ؛ 9 ؛ 12 ؛ 18 ؛ 36</span>، و لكلّ منها مقابله السالب"},{"quoi":"نحسب n في كل حالة","math":"نطرح 1 من كلّ قاسم للحصول على قيمة n"},{"quoi":"النتيجة","math":"القيم الممكنة لـ n هي<span dir=\"ltr\" class=\"expr\">: -37 ؛ -19 ؛ -13 ؛ -10 ؛ -7 ؛ -5 ؛ -4 ؛ -3 ؛ -2 ؛ 0 ؛ 1 ؛ 2 ؛ 3 ؛ 5 ؛ 8 ؛ 11 ؛ 17 ؛ 35</span>"}],
