    enonce: "احسب القيمة العددية لـ M إذا كان <span dir=\"ltr\" class=\"expr\">n = 35</span> علما أنّ <span dir=\"ltr\" class=\"expr\">M = (9n + 45)/(n + 1)</span>",
    correction: [{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">M = 9 + 36/(35 + 1)</span>"},{"quoi":"نحسب المقام","math":"<span dir=\"ltr\" class=\"expr\">35 + 1 = 36</span>"},{"quoi":"نحسب الكسر","math":"<span dir=\"ltr\" class=\"expr\">36 : 36 = 1</span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\">9 + 1 = 10</span>"},{"quoi":"نتحقّق بالشكل الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(9 × 35 + 45)/(35 + 1) = 10</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 10</span>"}],
